def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous non-background runs along each border.
    def runs(side):
        length = w if side in ("top", "bottom") else h
        fixed = 0 if side in ("top", "left") else (h - 1 if side == "bottom" else w - 1)
        vals = [grid[fixed][i] if side in ("top", "bottom") else grid[i][fixed]
                for i in range(length)]
        result = []
        i = 0
        while i < length:
            if vals[i] == bg:
                i += 1
                continue
            j = i
            while j + 1 < length and vals[j + 1] != bg:
                j += 1
            result.append((i, j))
            i = j + 1
        return result

    interior = [(r, c) for r in range(1, h - 1) for c in range(1, w - 1)
                if grid[r][c] != bg]
    if not interior:
        return out
    paint = Counter(grid[r][c] for r, c in interior).most_common(1)[0][0]

    # The two equal-length border runs define paired lanes. Interior marks
    # select lane offsets; each selected lane projects inward from both runs.
    pairs = []
    for a, b in (("top", "bottom"), ("left", "right")):
        ra, rb = runs(a), runs(b)
        for x in ra:
            for y in rb:
                if x[1] - x[0] == y[1] - y[0]:
                    pairs.append((a, x, b, y))

    for side1, seg1, side2, seg2 in pairs:
        length = seg1[1] - seg1[0] + 1
        active = set()
        for r, c in interior:
            pos = c if side1 in ("top", "bottom") else r
            if seg1[0] <= pos <= seg1[1]:
                active.add(pos - seg1[0])
            pos2 = c if side2 in ("top", "bottom") else r
            if seg2[0] <= pos2 <= seg2[1]:
                active.add(pos2 - seg2[0])

        for offset in active:
            for side, seg in ((side1, seg1), (side2, seg2)):
                lane = seg[0] + offset
                if side == "top":
                    cells = [(r, lane) for r in range(1, h)]
                elif side == "bottom":
                    cells = [(r, lane) for r in range(h - 2, -1, -1)]
                elif side == "left":
                    cells = [(lane, c) for c in range(1, w)]
                else:
                    cells = [(lane, c) for c in range(w - 2, -1, -1)]

                for r, c in cells:
                    if grid[r][c] != bg:
                        out[r][c] = 4
                        break
                    out[r][c] = paint

    return out
